import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";

export default function AddDriverForm() {
  const navigate = useNavigate();

  const [form, setForm] = useState({
    name: "",
    email: "",
    phone: "",
    licenseNumber: "",
    lat: "",
    lng: ""
  });

  const [success, setSuccess] = useState(false);
  const [error, setError] = useState("");

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    try {
      const response = await axios.post("http://localhost:5000/api/drivers", {
        ...form,
        isAvailable: true,
        currentOrders: 0,
        location: {
          lat: parseFloat(form.lat),
          lng: parseFloat(form.lng),
        },
      });

      console.log("Driver created:", response.data);
      setSuccess(true);
      setForm({
        name: "",
        email: "",
        phone: "",
        licenseNumber: "",
        lat: "",
        lng: ""
      });
    } catch (err) {
      console.error(err);
      setError("❌ Failed to create driver");
    }
  };

  return (
    <div style={{ padding: "40px", maxWidth: "500px", margin: "auto" }}>
      <h2 style={{ textAlign: "center" }}>Add Driver</h2>
      <form onSubmit={handleSubmit}>
        {["name", "email", "phone", "licenseNumber", "lat", "lng"].map((field) => (
          <input
            key={field}
            style={{ display: "block", width: "100%", marginBottom: "10px", padding: "10px" }}
            type="text"
            name={field}
            placeholder={field}
            value={(form as any)[field]}
            onChange={handleChange}
            required
          />
        ))}

        <button type="submit" style={{ padding: "10px 20px", marginRight: "10px" }}>
          Add Driver
        </button>

        {/* ✅ Back to Dashboard Button */}
        <button
          type="button"
          style={{ padding: "10px 20px", backgroundColor: "#6c757d", color: "#fff", border: "none", borderRadius: "4px" }}
          onClick={() => navigate("/")}
        >
          ← Back to Dashboard
        </button>
      </form>

      {success && (
        <div style={{ color: "green", marginTop: "15px", fontWeight: "bold" }}>
          ✅ Driver added successfully!
        </div>
      )}
      {error && (
        <div style={{ color: "red", marginTop: "15px", fontWeight: "bold" }}>
          {error}
        </div>
      )}
    </div>
  );
}
